css:
.controllersim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #e7edf5;
    background: linear-gradient(165deg, #0c1322 0%, #111b30 55%, #0d1626 100%);
    border-radius: 18px;
}

.controllersim-container * {
    box-sizing: border-box;
}

.controllersim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #13243f 0%, #1c3a63 55%, #275089 100%);
    color: #f3f7fc;
    border-radius: 16px;
    margin-bottom: 20px;
    border: 1px solid #28406a;
    box-shadow: 0 12px 32px rgba(0, 0, 0, 0.45);
}

.controllersim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.controllersim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #8fc7ff;
    background: rgba(143, 199, 255, 0.12);
    padding: 5px 14px;
    border-radius: 999px;
}

.controllersim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #cdddf2;
}

.controllersim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #aebfd6;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.controllersim-period-counter #currentDay,
.controllersim-period-counter #maxPeriods {
    font-weight: 800;
    color: #ffffff;
}

.controllersim-round-name {
    background: #1c3a63;
    color: #cfe4ff;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
    border: 1px solid #2c5089;
}

.controllersim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #ffcf8a;
    background: rgba(255, 158, 51, 0.14);
    padding: 4px 12px;
    border-radius: 999px;
    border: 1px solid rgba(255, 158, 51, 0.30);
}

.controllersim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.controllersim-status-card {
    background: #142133;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #243752;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.30);
    border-top: 4px solid #3d6db0;
}

.controllersim-card-control { border-top-color: #2e9e7a; }
.controllersim-card-cred { border-top-color: #3d8bdc; }
.controllersim-card-influence { border-top-color: #b88be0; }
.controllersim-card-capital { border-top-color: #e0a23c; }

.controllersim-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8597b3;
}

.controllersim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #ffffff;
    font-variant-numeric: tabular-nums;
}

.controllersim-card-control .controllersim-value { color: #4fd1a5; }
.controllersim-card-cred .controllersim-value { color: #6cb6f5; }
.controllersim-card-influence .controllersim-value { color: #cfa8ee; }
.controllersim-card-capital .controllersim-value { color: #f4bf63; }

.controllersim-sublabel {
    font-size: 0.74rem;
    color: #7e92b0;
    line-height: 1.35;
}

.controllersim-cred-low .controllersim-value { color: #f06d5a; }
.controllersim-cred-high .controllersim-value { color: #4fd1a5; }

.controllersim-influence-lost { border-top-color: #f06d5a; }
.controllersim-influence-lost .controllersim-value { color: #f06d5a; }

.controllersim-capital-safe { border-top-color: #2e9e7a; }
.controllersim-capital-safe .controllersim-value { color: #4fd1a5; }
.controllersim-capital-exposed { border-top-color: #f06d5a; }
.controllersim-capital-exposed .controllersim-value { color: #f06d5a; }

.controllersim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #0a1830;
    color: #cfe4ff;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
    border: 1px solid #1e3556;
}

.controllersim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #f4bf63;
}

.controllersim-briefing {
    display: flex;
    gap: 14px;
    background: #142133;
    border-left: 5px solid #3d8bdc;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    border: 1px solid #243752;
    border-left-width: 5px;
}

.controllersim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.controllersim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #ffffff;
    margin-bottom: 6px;
}

.controllersim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #c4d4ea;
}

.controllersim-briefing-text strong { color: #4fd1a5; }
.controllersim-briefing-text em { color: #ffcf8a; font-style: italic; }

.controllersim-controls {
    background: #142133;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #243752;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.30);
}

.controllersim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #ffffff;
    border-bottom: 2px solid #243752;
    padding-bottom: 8px;
}

.controllersim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #dbe6f5;
    margin: 14px 0 6px;
}

.controllersim-container select,
.controllersim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #2c466e;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #0d1a30;
    color: #e7edf5;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.controllersim-container select:focus,
.controllersim-container input[type="number"]:focus {
    outline: none;
    border-color: #3d8bdc;
    box-shadow: 0 0 0 3px rgba(61, 139, 220, 0.22);
}

.controllersim-container select option {
    background-color: #0d1a30;
    color: #e7edf5;
}

.controllersim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #3d8bdc;
}

.controllersim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #9fb6d6;
    margin-top: 4px;
}

.controllersim-range-readout span:last-child {
    color: #4fd1a5;
    font-weight: 800;
    font-variant-numeric: tabular-nums;
}

.controllersim-hint {
    font-size: 0.8rem;
    color: #7e92b0;
    margin-top: 4px;
    line-height: 1.4;
}

.controllersim-check-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 6px;
}

.controllersim-check-row {
    display: flex !important;
    align-items: flex-start;
    gap: 10px;
    background: #0f1d33;
    border: 1px solid #243752;
    border-radius: 9px;
    padding: 9px 12px;
    margin: 0 !important;
    font-weight: 600 !important;
    font-size: 0.88rem !important;
    color: #c4d4ea !important;
    cursor: pointer;
}

.controllersim-check-row input[type="checkbox"] {
    width: 18px;
    height: 18px;
    margin-top: 1px;
    flex: 0 0 18px;
    accent-color: #3d8bdc;
    cursor: pointer;
}

.controllersim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.controllersim-container .btn-primary {
    background: linear-gradient(135deg, #2e9e7a 0%, #3d8bdc 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    color: #ffffff;
    box-shadow: 0 8px 20px rgba(61, 139, 220, 0.30);
}

.controllersim-container .btn-primary:hover {
    filter: brightness(1.08);
}

.controllersim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #2c466e;
    color: #9fb6d6;
    background: transparent;
}

.controllersim-coach {
    background: linear-gradient(135deg, #0a1830 0%, #122544 100%);
    color: #d6e4f7;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    border: 1px solid #234066;
    box-shadow: 0 8px 22px rgba(0, 0, 0, 0.35);
}

.controllersim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #6cb6f5;
    margin-bottom: 8px;
}

.controllersim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.controllersim-coach-body strong { color: #f4bf63; }
.controllersim-coach-body em { color: #ffb7a3; font-style: italic; }

.controllersim-history,
.controllersim-chart {
    background: #142133;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #243752;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.30);
}

.controllersim-history h3,
.controllersim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #ffffff;
}

.controllersim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #c4d4ea;
}

.controllersim-container table#usfHistoryTable th {
    background: #0f1d33;
    color: #8fc7ff;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #243752;
}

.controllersim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #1c2c44;
    color: #c4d4ea;
}

.controllersim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #0f1d33;
}

.controllersim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .controllersim-container {
        padding: 14px;
    }
    .controllersim-header h1 {
        font-size: 1.7rem;
    }
    .controllersim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .controllersim-value {
        font-size: 2rem;
    }
    .controllersim-clock {
        margin-left: 0;
    }
    .controllersim-period-counter {
        font-size: 0.88rem;
    }
    .controllersim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .controllersim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen (controllersim) ---- */
.controllersim-completion { padding: 8px 4px 4px; }
.controllersim-cm-head { text-align: center; margin-bottom: 16px; }
.controllersim-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #4f7fc4; }
.controllersim-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #7c9dcb; }
.controllersim-cm-grade { font-size: 1.2rem; font-weight: 700; margin-top: 6px; color: #26303f; }
.controllersim-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.controllersim-cm-yes { background: rgba(79,127,196,0.16); color: #3a68a8; border: 1px solid rgba(79,127,196,0.55); }
.controllersim-cm-no { background: rgba(190,70,55,0.12); color: #a5412c; border: 1px solid rgba(190,70,55,0.45); }
.controllersim-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.controllersim-cm-metric { flex: 1 1 100px; min-width: 90px; background: rgba(79,127,196,0.08); border: 1px solid rgba(79,127,196,0.2); border-radius: 10px; padding: 10px 8px; text-align: center; }
.controllersim-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #3f6bab; }
.controllersim-cm-ml { display: block; font-size: 0.7rem; margin-top: 4px; color: #66707f; text-transform: uppercase; letter-spacing: 0.03em; }
.controllersim-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #26303f; }
.controllersim-cm-insights { margin: 0; padding-left: 20px; }
.controllersim-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #37414f; }

