(function() {
    'use strict';

    class ControllerAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `The Controller's Seat`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (concept §7).
            this.GROUP_REVENUE = 1900;     // €m
            this.DIV_REVENUE = 640;        // €m
            this.PLAN_REVENUE = 1300;      // €m, president's heroic target
            this.GROWTH = 660;             // €m promised growth (1300 - 640)
            this.UNSIGNED_SHARE = 0.62;    // 62% of growth rides on two unsigned contracts
            this.FORECAST_ERROR = 22;      // ±22% historical accuracy
            this.CAPITAL_REQUEST = 180;    // €m up front
            this.BONUS_POOL = 6.2;         // €m tied to the targets

            // Starting KPIs (match the seeds rendered in view.html).
            this.START_CONTROL = 30;
            this.START_CRED = 25;
            this.START_INFLUENCE = 40;
            this.START_CAPITAL = 180;      // €m exposed up front

            // Day-90 reference bands used in the end summary / hints.
            this.GOOD_BAND = 70;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    control: this.START_CONTROL,
                    cred: this.START_CRED,
                    influence: this.START_INFLUENCE,
                    capital: this.START_CAPITAL,
                    rubberStamped: false,
                    lostSeat: false,
                    noDecision: false,
                    controlHistory: [this.START_CONTROL],
                    credHistory: [this.START_CRED],
                    influenceHistory: [this.START_INFLUENCE],
                    capitalHistory: [this.START_CAPITAL],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seed MIDDLING / neutral — the numeric levers sit well below the
                // concept-correct calibration so a pure click-through cannot auto-win.
                state.decisions = {
                    bridge: `separate`,
                    benchmark: `outsideview`,
                    candor: 40,
                    balance: `balanced`,
                    ldPipeline: true,
                    ldQual: false,
                    ldRamp: false,
                    ldRevenue: false,
                    ldShare: false,
                    use: `both`,
                    philosophy: `counterflow`,
                    buffer: 10,
                    sandbag: `evidence`,
                    achiev: 50,
                    stance: `partner`,
                    gate: `gated`,
                    opinion: `gates`,
                    conviction: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const br = document.getElementById(`bridgeInput`);
                const bm = document.getElementById(`benchmarkInput`);
                const cd = document.getElementById(`candorInput`);
                if (br) decisions.bridge = br.value;
                if (bm) decisions.benchmark = bm.value;
                if (cd) decisions.candor = parseInt(cd.value, 10);
                if (!Number.isFinite(decisions.candor) || decisions.candor < 0 || decisions.candor > 100) {
                    warn(`warn_candor_range`); return false;
                }
            } else if (round === 2) {
                const bal = document.getElementById(`balanceInput`);
                const us = document.getElementById(`useInput`);
                if (bal) decisions.balance = bal.value;
                if (us) decisions.use = us.value;
                const ids = [`ldPipeline`, `ldQual`, `ldRamp`, `ldRevenue`, `ldShare`];
                ids.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) decisions[id] = !!el.checked;
                });
                const picked = ids.filter((id) => decisions[id]).length;
                if (picked < 2 || picked > 3) {
                    warn(`warn_leading_count`); return false;
                }
            } else if (round === 3) {
                const ph = document.getElementById(`philosophyInput`);
                const bf = document.getElementById(`bufferInput`);
                const sb = document.getElementById(`sandbagInput`);
                const ac = document.getElementById(`achievInput`);
                if (ph) decisions.philosophy = ph.value;
                if (sb) decisions.sandbag = sb.value;
                if (bf) decisions.buffer = parseInt(bf.value, 10);
                if (ac) decisions.achiev = parseInt(ac.value, 10);
                if (!Number.isFinite(decisions.buffer) || decisions.buffer < 0 || decisions.buffer > 60) {
                    warn(`warn_buffer_range`); return false;
                }
                if (!Number.isFinite(decisions.achiev) || decisions.achiev < 0 || decisions.achiev > 100) {
                    warn(`warn_achiev_range`); return false;
                }
            } else if (round === 4) {
                const st = document.getElementById(`stanceInput`);
                const gt = document.getElementById(`gateInput`);
                const op = document.getElementById(`opinionInput`);
                const cv = document.getElementById(`convictionInput`);
                if (st) decisions.stance = st.value;
                if (gt) decisions.gate = gt.value;
                if (op) decisions.opinion = op.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Deltas on the three 0–100 KPIs; capital is set directly in round 4.
            let controlDelta = 0, credDelta = 0, influenceDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // --- Diagnose the plan & the forecast ---
                // Revenue bridge: separate committed from speculative (Common Error 1).
                switch (d.bridge) {
                    case `separate`: controlDelta += 6; credDelta += 6; coachKey = `coach_r1_separate`; break;
                    case `probable`: controlDelta += 1; credDelta -= 5; coachKey = `coach_r1_probable`; break;
                    case `endorse`: controlDelta -= 11; credDelta -= 13; ds.rubberStamped = true; coachKey = `coach_r1_endorse`; break;
                }

                // Outside view vs trusting the trend (optimism bias).
                switch (d.benchmark) {
                    case `outsideview`: controlDelta += 5; credDelta += 4; if (d.bridge === `separate`) coachKey = `coach_r1_sharp`; break;
                    case `trend`: controlDelta -= 9; credDelta -= 9; ds.rubberStamped = true; coachKey = `coach_r1_trend`; break;
                    case `ignore`: controlDelta -= 13; credDelta -= 7; coachKey = `coach_r1_ignore`; break;
                }

                // Candor in naming sandbag + stretch — evidence not blame. A heavy lever:
                // a middling 40 leaves real points on the table versus a candid 70+.
                if (d.candor >= 70) { controlDelta += 7; credDelta += 7; }
                else if (d.candor >= 45) { controlDelta += 3; credDelta += 2; }
                else { controlDelta -= 6; credDelta -= 7; if (d.candor <= 25) coachKey = `coach_r1_lowcandor`; }

                summaryKey = (d.bridge === `separate` && d.benchmark === `outsideview` && d.candor >= 70) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // --- Design the KPI architecture (Common Error 2) ---
                switch (d.balance) {
                    case `balanced`: controlDelta += 6; credDelta += 5; coachKey = `coach_r2_balanced`; break;
                    case `financeonly`: controlDelta -= 9; credDelta -= 2; coachKey = `coach_r2_financeonly`; break;
                    case `vanity`: controlDelta -= 7; credDelta -= 4; coachKey = `coach_r2_vanity`; break;
                }

                // Leading-indicator selection. Pipeline, qualification and ramp are the
                // genuine early-warning trio; revenue is lagging, share price is noise.
                // Picking the full trio (3) instead of the bare minimum (2) is a real lever.
                const good = (d.ldPipeline ? 1 : 0) + (d.ldQual ? 1 : 0) + (d.ldRamp ? 1 : 0);
                const lagging = (d.ldRevenue ? 1 : 0);
                const noise = (d.ldShare ? 1 : 0);
                controlDelta += good * 2;
                if (lagging) { controlDelta -= 7; coachKey = `coach_r2_lagging`; }
                if (noise) { controlDelta -= 8; credDelta -= 4; coachKey = `coach_r2_noise`; }
                if (good === 3 && !lagging && !noise) { controlDelta += 3; credDelta += 5; coachKey = `coach_r2_leadingsharp`; }

                // Diagnostic + interactive use with the president (Simons).
                switch (d.use) {
                    case `both`: controlDelta += 3; influenceDelta += 11; coachKey = (good >= 2 && !noise) ? coachKey : `coach_r2_both`; break;
                    case `diagnostic`: controlDelta += 1; influenceDelta -= 3; coachKey = `coach_r2_diagnostic`; break;
                    case `report`: controlDelta -= 6; influenceDelta -= 9; coachKey = `coach_r2_report`; break;
                }

                summaryKey = (d.balance === `balanced` && good >= 2 && !noise && d.use === `both`) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // --- Set the budget targets (Common Error 3) ---
                switch (d.philosophy) {
                    case `counterflow`: controlDelta += 5; credDelta += 5; coachKey = `coach_r3_counterflow`; break;
                    case `topdown`: controlDelta -= 7; credDelta -= 10; coachKey = `coach_r3_topdown`; break;
                    case `bottomup`: controlDelta -= 9; credDelta -= 6; coachKey = `coach_r3_bottomup`; break;
                }

                // Contingency buffer for the unsigned-contract risk. 62% of growth is
                // speculative; a 25–40% holdback is calibrated. Too little or too much loses.
                // Heavy lever: the seeded 10 sits in the thin-buffer penalty band.
                if (d.buffer >= 25 && d.buffer <= 40) { credDelta += 7; controlDelta += 3; }
                else if (d.buffer >= 15 && d.buffer < 25) { credDelta += 2; }
                else if (d.buffer < 15) { credDelta -= 10; coachKey = `coach_r3_thinbuffer`; }
                else { controlDelta -= 7; coachKey = `coach_r3_fatbuffer`; }

                // Handle the sandbagging.
                switch (d.sandbag) {
                    case `evidence`: controlDelta += 5; credDelta += 4; influenceDelta += 3; break;
                    case `bake`: controlDelta -= 10; credDelta -= 9; coachKey = `coach_r3_bake`; break;
                    case `hunt`: controlDelta += 1; influenceDelta -= 11; credDelta -= 4; coachKey = `coach_r3_hunt`; break;
                }

                // Honest target-achievement probability. Given ±22% error and 62% unsigned,
                // an honest realistic-scenario number sits ~55–72%; 90+ is the rubber stamp.
                // Heavy lever: the seeded 50 sits in the underconfident penalty band.
                if (d.achiev >= 55 && d.achiev <= 72) { credDelta += 7; controlDelta += 3; }
                else if (d.achiev > 72) { credDelta -= 11; ds.rubberStamped = true; coachKey = `coach_r3_overconfident`; }
                else { credDelta -= 7; coachKey = `coach_r3_underconfident`; }

                summaryKey = (d.philosophy === `counterflow` && d.sandbag === `evidence` && d.buffer >= 25 && d.buffer <= 40) ? `sum_r3_good` : `sum_r3_weak`;
            } else if (round === 4) {
                // --- Challenge the strategy & write the opinion (Common Errors 4 & 5) ---
                switch (d.stance) {
                    case `partner`: controlDelta += 6; influenceDelta += 16; credDelta += 4; coachKey = `coach_r4_partner`; break;
                    case `scorekeeper`: controlDelta += 2; influenceDelta -= 2; credDelta -= 4; coachKey = `coach_r4_scorekeeper`; break;
                    case `adversary`: controlDelta += 4; influenceDelta -= 22; ds.lostSeat = true; coachKey = `coach_r4_adversary`; break;
                }

                // Milestone-gated (real-options) capital release sets capital exposed.
                switch (d.gate) {
                    case `gated`: ds.capital = 55; controlDelta += 5; credDelta += 6; coachKey = (d.stance === `partner`) ? `coach_r4_partnergate` : coachKey; break;
                    case `upfront`: ds.capital = 180; controlDelta -= 11; credDelta -= 13; ds.rubberStamped = true; coachKey = `coach_r4_upfront`; break;
                    case `freeze`: ds.capital = 0; controlDelta += 2; influenceDelta -= 13; credDelta -= 6; coachKey = `coach_r4_freeze`; break;
                }

                // The controlling opinion the board can act on (Common Error 5).
                switch (d.opinion) {
                    case `gates`: controlDelta += 4; credDelta += 6; influenceDelta += 5; break;
                    case `approve`: controlDelta -= 11; credDelta -= 15; ds.rubberStamped = true; coachKey = `coach_r4_approve`; break;
                    case `reshape`: controlDelta += 3; credDelta += 1; influenceDelta -= 7; coachKey = `coach_r4_reshape`; break;
                    case `risks`: controlDelta -= 6; credDelta -= 10; ds.noDecision = true; coachKey = `coach_r4_norisk`; break;
                }

                // Conviction defending the opinion with the president in the room. Heavy lever:
                // the seeded 60 misses the firm-conviction band.
                if (d.conviction >= 70) { influenceDelta += 8; credDelta += 6; }
                else if (d.conviction >= 50) { influenceDelta += 2; credDelta += 1; }
                else if (d.conviction <= 35) { influenceDelta -= 6; credDelta -= 5; coachKey = `coach_r4_lowconviction`; }

                summaryKey = (d.stance === `partner` && d.gate === `gated` && d.opinion === `gates`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Apply deltas with floors/caps. Headroom preserved by starting low (30/25/40).
            ds.control = Math.max(0, Math.min(100, ds.control + controlDelta));
            ds.cred = Math.max(0, Math.min(100, ds.cred + credDelta));
            ds.influence = Math.max(0, Math.min(100, ds.influence + influenceDelta));
            ds.capital = Math.max(0, Math.min(this.CAPITAL_REQUEST, ds.capital));

            ds.controlHistory.push(Math.round(ds.control));
            ds.credHistory.push(Math.round(ds.cred));
            ds.influenceHistory.push(Math.round(ds.influence));
            ds.capitalHistory.push(Math.round(ds.capital));

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing(window.mySimulation.state);
            }, 500);

            // Expose composite (0-100) to the reporting/grading layer every period
            // (express/results_utils.php::express_resolveDomainScore reads domainState.performance.overallScore).
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                control: Math.round(ds.control),
                controlDelta: Math.round(controlDelta),
                cred: Math.round(ds.cred),
                credDelta: Math.round(credDelta),
                influence: Math.round(ds.influence),
                influenceDelta: Math.round(influenceDelta),
                capital: Math.round(ds.capital),
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

