        // Composite (0-100) written to domainState.performance.overallScore each period for the
        // reporting/grading layer. Formula (incl. banded capitalScore) copied VERBATIM from v1.0.0.
        _composite(ds) {
            const control = Math.round(ds.control);
            const cred = Math.round(ds.cred);
            const influence = Math.round(ds.influence);
            const capital = Math.round(ds.capital);
            let capitalScore;
            if (capital <= 80 && capital >= 40) capitalScore = 100;
            else if (capital < 40) capitalScore = 70 + Math.round((capital / 40) * 30);
            else capitalScore = Math.max(0, Math.round(100 - ((capital - 80) / (this.CAPITAL_REQUEST - 80)) * 100));
            return Math.max(0, Math.min(100, Math.round(control * 0.30 + cred * 0.30 + influence * 0.22 + capitalScore * 0.18)));
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.overallScore === `number`) ? s.overallScore
                : (typeof s.totalScore === `number` ? s.totalScore
                : (typeof s.composite === `number` ? s.composite : 0));
            const grade = s.performance || (s.performanceKey ? T(s.performanceKey) : ``);
            const met = !!s.met;
            const badge = met
                ? `<span class="controllersim-cm-badge controllersim-cm-yes">` + T(`cm_met`) + `</span>`
                : `<span class="controllersim-cm-badge controllersim-cm-no">` + T(`cm_notmet`) + `</span>`;
            let failBadge = ``;
            if (s.lostSeat) failBadge += ` <span class="controllersim-cm-badge controllersim-cm-no">` + T(`cm_lostseat`) + `</span>`;
            if (s.rubberStamped) failBadge += ` <span class="controllersim-cm-badge controllersim-cm-no">` + T(`cm_rubber`) + `</span>`;
            if (s.noDecision) failBadge += ` <span class="controllersim-cm-badge controllersim-cm-no">` + T(`cm_nodecision`) + `</span>`;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const metrics = ``
                + `<div class="controllersim-cm-metric"><span class="controllersim-cm-mv">` + Math.round(s.control || 0) + `</span><span class="controllersim-cm-ml">` + T(`cm_m_control`) + `</span></div>`
                + `<div class="controllersim-cm-metric"><span class="controllersim-cm-mv">` + Math.round(s.cred || 0) + `</span><span class="controllersim-cm-ml">` + T(`cm_m_cred`) + `</span></div>`
                + `<div class="controllersim-cm-metric"><span class="controllersim-cm-mv">` + Math.round(s.influence || 0) + `</span><span class="controllersim-cm-ml">` + T(`cm_m_influence`) + `</span></div>`
                + `<div class="controllersim-cm-metric"><span class="controllersim-cm-mv">` + Math.round(s.capital || 0) + `</span><span class="controllersim-cm-ml">` + T(`cm_m_capital`) + `</span></div>`;
            return ``
                + `<div class="controllersim-completion">`
                +   `<div class="controllersim-cm-head">`
                +     `<div class="controllersim-cm-score">` + score + `<span class="controllersim-cm-score-max">/100</span></div>`
                +     `<div class="controllersim-cm-grade">` + grade + ` ` + badge + failBadge + `</div>`
                +   `</div>`
                +   `<div class="controllersim-cm-metrics">` + metrics + `</div>`
                +   `<div class="controllersim-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="controllersim-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const t = window.mySimulation.t.bind(window.mySimulation);
            const control = Math.round(ds.control);
            const cred = Math.round(ds.cred);
            const influence = Math.round(ds.influence);
            const capital = Math.round(ds.capital);

            // Capital safety as a band, not a monotone "lower is better": the milestone-gated
            // tranche (~40–80 exposed) is the real-options optimum. Releasing all €180M up front
            // over-exposes the division; freezing all capital (0) starves the strategy and is its
            // own error — so both extremes score below the gated band.
            let capitalScore;
            if (capital <= 80 && capital >= 40) capitalScore = 100;            // gated tranche — ideal
            else if (capital < 40) capitalScore = 70 + Math.round((capital / 40) * 30); // freeze→under-investment
            else capitalScore = Math.max(0, Math.round(100 - ((capital - 80) / (this.CAPITAL_REQUEST - 80)) * 100)); // over-exposure
            const composite = this._composite(ds);

            // The three classic-error verdicts take precedence over any composite tier
            // so a high analytical score can't mask a stance, decision or debiasing failure.
            const trusted = composite >= 80 && influence >= 50 && capital >= 40 && capital <= 80 && !ds.rubberStamped && !ds.noDecision && !ds.lostSeat;
            let performanceKey;
            if (ds.lostSeat) performanceKey = `grade_lostseat`;
            else if (ds.rubberStamped) performanceKey = `grade_rubber`;
            else if (ds.noDecision) performanceKey = `grade_nodecision`;
            else if (trusted) performanceKey = `grade_trusted`;
            else if (composite >= 65) performanceKey = `grade_credible`;
            else if (composite >= 45) performanceKey = `grade_partial`;
            else performanceKey = `grade_prevention`;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (trusted) insights.push(t(`insight_trusted`));
            else if (composite >= 65 && !ds.rubberStamped && !ds.lostSeat && !ds.noDecision) insights.push(t(`insight_credible`));
            else insights.push(t(`insight_weak`));

            if (ds.rubberStamped) insights.push(t(`insight_rubberstamp`));
            if (ds.lostSeat) insights.push(t(`insight_lostseat`));
            if (ds.noDecision) insights.push(t(`insight_nodecision`));
            if (capital >= 40 && capital <= 80) insights.push(t(`insight_gated`));
            else if (capital > 120) insights.push(t(`insight_exposed`));
            else if (capital < 40) insights.push(t(`insight_starved`));

            return {
                control: control,
                cred: cred,
                influence: influence,
                capital: capital,
                capitalScore: capitalScore,
                rubberStamped: ds.rubberStamped,
                lostSeat: ds.lostSeat,
                noDecision: ds.noDecision,
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                met: trusted,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            const t = window.mySimulation.t.bind(window.mySimulation);
            if (ds.lostSeat) return t(`hint_lostseat`);
            if (ds.rubberStamped) return t(`hint_rubberstamp`);
            if (ds.influence < 25) return t(`hint_influence`);
            if (state.currentPeriod >= 3 && ds.cred < 45) return t(`hint_cred`);
            if (ds.control >= 70 && ds.cred >= 70 && ds.influence >= 55) return t(`hint_strong`);
            return null;
        }

