                    warn_candor_range:      `Tu nivel de franqueza debe ser un porcentaje entre 0 y 100.`,
                    warn_leading_count:     `Elige 2 o 3 indicadores adelantados — un conjunto enfocado, no los cinco ni solo uno.`,
